import { PatientRecord } from '../types';

/**
 * Parses a CSV string into an array of PatientRecord objects.
 * Handles quoted fields containing delimiters.
 */
export const parseCSV = (csvText: string): PatientRecord[] => {
  const lines = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length === 0) return [];

  const headers = parseCSVLine(lines[0]);
  const data: PatientRecord[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseCSVLine(lines[i]);
    if (values.length === headers.length) {
      const record: PatientRecord = {};
      headers.forEach((header, index) => {
        // Clean header name to be safe keys
        const cleanHeader = header.trim(); 
        record[cleanHeader] = values[index];
      });
      // Ensure we have a unique ID. If NU_NOTIFIC is missing, generate a temporary one
      if (!record['NU_NOTIFIC']) {
        record['NU_NOTIFIC'] = `TEMP-${Date.now()}-${i}`;
      }
      data.push(record);
    }
  }

  return data;
};

/**
 * Helper to parse a single CSV line handling quotes.
 */
const parseCSVLine = (text: string): string[] => {
  const result: string[] = [];
  let start = 0;
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    if (text[i] === '"') {
      inQuotes = !inQuotes;
    } else if (text[i] === ';' && !inQuotes) { // Assuming SINAN often uses ';' or ','
      // Check delimiter. Let's try to detect, but SINAN usually is ';' separated or ','
      // For this implementation, we will assume standard ',' but fallback if lines look like ';'
      // Actually, let's strictly split by separator found in header.
      // Re-implementing strictly for generic separator later.
      // For now, let's assume standard CSV parser logic for comma, 
      // but usually SINAN exports might be semi-colon.
      // Let's stick to standard CSV (comma) for the interface requirement.
    }
  }

  // Simple regex based parser for standard CSV
  const re_valid = /^\s*(?:'[^'\\]*(?:\\[\S\s][^'\\]*)*'|"[^"\\]*(?:\\[\S\s][^"\\]*)*"|[^,'"\s\\]*(?:\s+[^,'"\s\\]+)*)\s*(?:,\s*(?:'[^'\\]*(?:\\[\S\s][^'\\]*)*'|"[^"\\]*(?:\\[\S\s][^"\\]*)*"|[^,'"\s\\]*(?:\s+[^,'"\s\\]+)*)\s*)*$/;

  // Robust simple split for Comma or Semicolon detection
  const separator = text.indexOf(';') > -1 && text.indexOf(',') === -1 ? ';' : ',';

  let currentField = '';
  inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === separator && !inQuotes) {
      result.push(cleanField(currentField));
      currentField = '';
    } else {
      currentField += char;
    }
  }
  result.push(cleanField(currentField));

  return result;
};

const cleanField = (field: string): string => {
  let f = field.trim();
  if (f.startsWith('"') && f.endsWith('"')) {
    f = f.substring(1, f.length - 1);
  }
  return f;
};

export const generateCSV = (data: PatientRecord[]): string => {
  if (data.length === 0) return '';
  const headers = Object.keys(data[0]);
  const csvRows = [
    headers.join(','), // Header row
    ...data.map(row => headers.map(fieldName => {
      const val = row[fieldName] || '';
      // Escape quotes and wrap in quotes if contains comma
      const escaped = val.replace(/"/g, '""');
      return `"${escaped}"`;
    }).join(','))
  ];
  return csvRows.join('\n');
};

import React, { useMemo } from 'react';
import { PatientRecord } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip as RechartsTooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid, Legend } from 'recharts';

interface DashboardProps {
  data: PatientRecord[];
}

const COLORS = ['#00ffa2', '#ef4444', '#f59e0b', '#3b82f6', '#8b5cf6'];

const Dashboard: React.FC<DashboardProps> = ({ data }) => {
  const stats = useMemo(() => {
    const total = data.length;
    let cured = 0;
    let active = 0;
    let abandoned = 0;
    let deaths = 0;

    data.forEach(p => {
      const situacao = p['SITUA_ENCE'] ? p['SITUA_ENCE'].toLowerCase() : '';
      if (situacao.includes('cura')) cured++;
      else if (situacao.includes('abandono')) abandoned++;
      else if (situacao.includes('óbito')) deaths++;
      else active++;
    });

    return { total, cured, active, abandoned, deaths };
  }, [data]);

  const outcomeData = [
    { name: 'Cura', value: stats.cured },
    { name: 'Em Tratamento', value: stats.active },
    { name: 'Abandono', value: stats.abandoned },
    { name: 'Óbito', value: stats.deaths },
  ].filter(d => d.value > 0);

  const genderData = useMemo(() => {
    const counts: Record<string, number> = { M: 0, F: 0, I: 0 };
    data.forEach(p => {
      const sex = p['CS_SEXO'] || 'I';
      if (counts[sex] !== undefined) counts[sex]++;
      else counts['I']++;
    });
    return [
      { name: 'Masculino', value: counts.M },
      { name: 'Feminino', value: counts.F },
      { name: 'Ignorado', value: counts.I }
    ];
  }, [data]);

  return (
    <div className="space-y-6 animate-fade-in">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-card p-6 rounded-lg border border-gray-800 shadow-sm">
          <p className="text-secondary text-sm font-medium">Total Pacientes</p>
          <p className="text-3xl font-bold text-white mt-2">{stats.total}</p>
        </div>
        <div className="bg-card p-6 rounded-lg border border-gray-800 shadow-sm relative overflow-hidden">
          <div className="absolute top-0 right-0 w-2 h-full bg-primary opacity-50"></div>
          <p className="text-secondary text-sm font-medium">Cura Confirmada</p>
          <p className="text-3xl font-bold text-primary mt-2">{stats.cured}</p>
          <p className="text-xs text-secondary mt-1">{((stats.cured / stats.total) * 100).toFixed(1)}% do total</p>
        </div>
        <div className="bg-card p-6 rounded-lg border border-gray-800 shadow-sm">
          <p className="text-secondary text-sm font-medium">Abandono</p>
          <p className="text-3xl font-bold text-red-500 mt-2">{stats.abandoned}</p>
        </div>
        <div className="bg-card p-6 rounded-lg border border-gray-800 shadow-sm">
          <p className="text-secondary text-sm font-medium">Óbitos</p>
          <p className="text-3xl font-bold text-orange-500 mt-2">{stats.deaths}</p>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-card p-6 rounded-lg border border-gray-800 shadow-sm">
          <h3 className="text-lg font-semibold text-white mb-4">Desfecho do Tratamento</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={outcomeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {outcomeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <RechartsTooltip 
                    contentStyle={{ backgroundColor: '#1f2937', borderColor: '#374151', color: '#fff' }}
                />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-card p-6 rounded-lg border border-gray-800 shadow-sm">
          <h3 className="text-lg font-semibold text-white mb-4">Distribuição por Sexo</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={genderData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                <XAxis dataKey="name" stroke="#9ca3af" />
                <YAxis stroke="#9ca3af" />
                <RechartsTooltip 
                    cursor={{fill: '#374151', opacity: 0.2}}
                    contentStyle={{ backgroundColor: '#1f2937', borderColor: '#374151', color: '#fff' }}
                />
                <Bar dataKey="value" fill="#00ffa2" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { PatientRecord } from '../types';
import { FIELD_GROUPS, FIELD_DICTIONARY, DEFAULT_FIELD_DEF } from '../constants';

interface PatientFormProps {
  initialData?: PatientRecord;
  onSave: (data: PatientRecord) => void;
  onCancel: () => void;
}

const PatientForm: React.FC<PatientFormProps> = ({ initialData, onSave, onCancel }) => {
  // Initialize with initial data or empty object
  const [formData, setFormData] = useState<PatientRecord>(initialData || {});
  const [activeTab, setActiveTab] = useState(0);

  const handleChange = (id: string, value: string) => {
    setFormData(prev => ({ ...prev, [id]: value }));
  };

  const getFieldDef = (id: string) => {
    return FIELD_DICTIONARY[id] || { ...DEFAULT_FIELD_DEF, id, label: id };
  };

  return (
    <div className="bg-card border border-gray-800 rounded-lg shadow-xl overflow-hidden flex flex-col h-full max-h-[85vh]">
      {/* Header */}
      <div className="bg-sidebar px-6 py-4 border-b border-gray-700 flex justify-between items-center shrink-0">
        <div>
          <h2 className="text-xl font-bold text-white">Prontuário Eletrônico</h2>
          <p className="text-sm text-secondary">
            {formData['NU_NOTIFIC'] ? `Notificação: ${formData['NU_NOTIFIC']}` : 'Novo Registro'}
          </p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={onCancel}
            className="px-4 py-2 rounded-md bg-transparent border border-gray-600 text-gray-300 hover:bg-gray-800 transition-colors"
          >
            Cancelar
          </button>
          <button 
            onClick={() => onSave(formData)}
            className="px-4 py-2 rounded-md bg-primary text-black font-semibold hover:bg-emerald-400 transition-colors shadow-[0_0_10px_rgba(0,255,162,0.3)]"
          >
            Salvar Prontuário
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex overflow-x-auto bg-sidebar border-b border-gray-700 px-2 shrink-0">
        {FIELD_GROUPS.map((group, index) => (
          <button
            key={index}
            onClick={() => setActiveTab(index)}
            className={`px-4 py-3 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${
              activeTab === index 
                ? 'border-primary text-primary' 
                : 'border-transparent text-gray-400 hover:text-white hover:border-gray-600'
            }`}
          >
            {group.title}
          </button>
        ))}
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-6 bg-background custom-scrollbar">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {FIELD_GROUPS[activeTab].fields.map((fieldId) => {
            const def = getFieldDef(fieldId);
            return (
              <div key={fieldId} className="flex flex-col space-y-1">
                <div className="flex justify-between items-baseline">
                  <label className="text-xs font-semibold text-secondary uppercase tracking-wider" htmlFor={fieldId}>
                    {def.label}
                  </label>
                  <span className="text-[10px] text-gray-600 cursor-help" title={def.description}>[?]</span>
                </div>

                {def.options ? (
                  <select
                    id={fieldId}
                    value={formData[fieldId] || ''}
                    onChange={(e) => handleChange(fieldId, e.target.value)}
                    className="bg-sidebar border border-gray-700 text-white text-sm rounded-md focus:ring-1 focus:ring-primary focus:border-primary block w-full p-2.5"
                  >
                    <option value="">Selecione...</option>
                    {def.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : (
                  <input
                    type={def.type === 'date' ? 'date' : 'text'}
                    id={fieldId}
                    value={formData[fieldId] || ''}
                    onChange={(e) => handleChange(fieldId, e.target.value)}
                    className="bg-sidebar border border-gray-700 text-white text-sm rounded-md focus:ring-1 focus:ring-primary focus:border-primary block w-full p-2.5 placeholder-gray-600"
                    placeholder="Vazio"
                  />
                )}
                <p className="text-[10px] text-gray-500 h-3 truncate">{def.description}</p>
              </div>
            );
          })}

          {/* Add extra fields catcher for the last tab if wanted, or specific logic to show raw unused fields could be added here */}
        </div>
      </div>
    </div>
  );
};

export default PatientForm;

