                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-700">
                        {Object.entries(field.optionsMap || {}).map(([code, meaning]) => (
                          <tr key={code} className="hover:bg-white/5">
                            <td className="px-4 py-2 font-mono text-white">{code}</td>
                            <td className="px-4 py-2 text-gray-400">{meaning}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

