import { PatientRecord } from '../types';

/**
 * Parses a CSV string into an array of PatientRecord objects.
 * Handles quoted fields containing delimiters.
 */
export const parseCSV = (csvText: string): PatientRecord[] => {
  const lines = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length === 0) return [];

  const headers = parseCSVLine(lines[0]);
  const data: PatientRecord[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = parseCSVLine(lines[i]);
    if (values.length === headers.length) {
      const record: PatientRecord = {};
      headers.forEach((header, index) => {
        // Clean header name to be safe keys
        const cleanHeader = header.trim(); 
        record[cleanHeader] = values[index];
      });
      // Ensure we have a unique ID. If NU_NOTIFIC is missing, generate a temporary one
      if (!record['NU_NOTIFIC']) {
        record['NU_NOTIFIC'] = `TEMP-${Date.now()}-${i}`;
      }
      data.push(record);
    }
  }

  return data;
};

/**
 * Helper to parse a single CSV line handling quotes.
 */
const parseCSVLine = (text: string): string[] => {
  const result: string[] = [];
  // Robust simple split for Comma or Semicolon detection
  const separator = text.indexOf(';') > -1 && text.indexOf(',') === -1 ? ';' : ',';

  let currentField = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === separator && !inQuotes) {
      result.push(cleanField(currentField));
      currentField = '';
    } else {
      currentField += char;
    }
  }
  result.push(cleanField(currentField));

  return result;
};

const cleanField = (field: string): string => {
  let f = field.trim();
  if (f.startsWith('"') && f.endsWith('"')) {
    f = f.substring(1, f.length - 1);
  }
  return f;
};

export const generateCSV = (data: PatientRecord[]): string => {
  if (data.length === 0) return '';
  const headers = Object.keys(data[0]);
  const csvRows = [
    headers.join(','), // Header row
    ...data.map(row => headers.map(fieldName => {
      const val = row[fieldName] || '';
      // Escape quotes and wrap in quotes if contains comma
      const escaped = val.replace(/"/g, '""');
      return `"${escaped}"`;
    }).join(','))
  ];
  return csvRows.join('\n');
};

// --- DATE HELPERS ---

/**
 * Converts SINAN CSV Date (DD/MM/YYYY) to HTML Input Date (YYYY-MM-DD)
 */
export const toInputDate = (csvDate: string): string => {
  if (!csvDate) return '';
  // Check if already in YYYY-MM-DD (sometimes happens)
  if (csvDate.match(/^\d{4}-\d{2}-\d{2}$/)) return csvDate;

  const parts = csvDate.split('/');
  if (parts.length === 3) {
    // DD/MM/YYYY -> YYYY-MM-DD
    return `${parts[2]}-${parts[1]}-${parts[0]}`;
  }
  return csvDate; // Return as is if format unknown
};

/**
 * Converts HTML Input Date (YYYY-MM-DD) to SINAN CSV Date (DD/MM/YYYY)
 */
export const fromInputDate = (inputDate: string): string => {
  if (!inputDate) return '';
  const parts = inputDate.split('-');
  if (parts.length === 3) {
    // YYYY-MM-DD -> DD/MM/YYYY
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  }
  return inputDate;
};

import React, { useState } from 'react';
import { PatientRecord, FieldDefinition } from './types';
import { parseCSV, generateCSV } from './services/csvService';
import Dashboard from './components/Dashboard';
import PatientList from './components/PatientList';
import PatientForm from './components/PatientForm';
import DictionaryModal from './components/DictionaryModal';
import { FIELD_DICTIONARY } from './constants';

type ViewMode = 'dashboard' | 'list' | 'form';

function App() {
  const [data, setData] = useState<PatientRecord[]>([]);
  const [view, setView] = useState<ViewMode>('dashboard');
  const [selectedPatient, setSelectedPatient] = useState<PatientRecord | undefined>(undefined);
  const [showDictionary, setShowDictionary] = useState(false);
  const [fileName, setFileName] = useState<string>('');

  // Editable Dictionary State
  const [dictionary, setDictionary] = useState<Record<string, FieldDefinition>>(FIELD_DICTIONARY);

  // Handle File Upload
  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      setFileName(file.name);
      const reader = new FileReader();
      reader.onload = (e) => {
        const text = e.target?.result as string;
        const parsedData = parseCSV(text);
        setData(parsedData);
      };
      reader.readAsText(file);
    }
  };

  // Handle Export
  const handleExport = () => {
    const csvContent = generateCSV(data);
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'export_sinan_tb.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // CRUD Operations
  const handleSavePatient = (patient: PatientRecord) => {
    const isNew = !data.some(p => p['NU_NOTIFIC'] === patient['NU_NOTIFIC']);

    if (isNew) {
      setData(prev => [...prev, patient]);
    } else {
      setData(prev => prev.map(p => p['NU_NOTIFIC'] === patient['NU_NOTIFIC'] ? patient : p));
    }
    setView('list');
    setSelectedPatient(undefined);
  };

  const handleDeletePatient = (id: string) => {
    setData(prev => prev.filter(p => p['NU_NOTIFIC'] !== id));
  };

  const startEdit = (patient: PatientRecord) => {
    setSelectedPatient(patient);
    setView('form');
  };

  const startNew = () => {
    setSelectedPatient(undefined);
    setView('form');
  };

  const handleUpdateDictionary = (updatedFields: Record<string, FieldDefinition>) => {
    setDictionary(updatedFields);
  };

  return (
    <div className="flex h-screen bg-background font-sans text-text overflow-hidden">
