import React, { useState, useMemo } from 'react';
import { PatientRecord, FieldDefinition } from '../types';
import { getGeoByCode } from '../sinan_geo';
import { generateTeamReport } from '../services/reportService';

interface PatientListProps {
  data: PatientRecord[];
  dictionary: Record<string, FieldDefinition>;
  onEdit: (patient: PatientRecord) => void;
  onDelete: (id: string) => void;
}

const PatientList: React.FC<PatientListProps> = ({ data, dictionary, onEdit, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRegion, setFilterRegion] = useState('');
  const [filterRA, setFilterRA] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterMonth, setFilterMonth] = useState('');
  const [page, setPage] = useState(1);
  const itemsPerPage = 15;

  // Get Status Options from Dictionary
  const statusOptions = dictionary['Status']?.options || [];

  // Helper to extract MM/YYYY from DD/MM/YYYY
  const getNotificationMonth = (dateStr: string) => {
    if (!dateStr || dateStr.length < 10) return '';
    const parts = dateStr.split('/');
    if (parts.length === 3) {
      return `${parts[1]}/${parts[2]}`; // MM/YYYY
    }
    return '';
  };

  // Derive geo options and month options from current data
  const filterOptions = useMemo(() => {
     const regions = new Set<string>();
     const ras = new Set<string>();
     const months = new Set<string>();

     data.forEach(p => {
        const geo = getGeoByCode(p['ID_BAIRRO']);
        if (geo) {
          regions.add(geo.regiao_saude);
          ras.add(geo.ra);
        }
        const month = getNotificationMonth(p['DT_NOTIFIC']);
        if (month) months.add(month);
     });

     // Sort months chronologically (MM/YYYY) is tricky to sort alphabetically, so we do custom sort
     const sortedMonths = Array.from(months).sort((a, b) => {
       const [ma, ya] = a.split('/').map(Number);
       const [mb, yb] = b.split('/').map(Number);
       return (ya * 12 + ma) - (yb * 12 + mb);
     });

     return { 
       regions: Array.from(regions).sort(), 
       ras: Array.from(ras).sort(),
       months: sortedMonths.reverse() // Newest first
     };
  }, [data]);

  const filteredData = data.filter(p => {
    const term = searchTerm.toLowerCase();
    const geo = getGeoByCode(p['ID_BAIRRO']);
    const notifMonth = getNotificationMonth(p['DT_NOTIFIC']);

    const matchesTerm = (
      (p['NM_PACIENT'] && p['NM_PACIENT'].toLowerCase().includes(term)) ||
      (p['NU_NOTIFIC'] && p['NU_NOTIFIC'].toLowerCase().includes(term))
    );

    const matchesRegion = filterRegion ? geo?.regiao_saude === filterRegion : true;
    const matchesRA = filterRA ? geo?.ra === filterRA : true;
    const matchesStatus = filterStatus ? p['Status'] === filterStatus : true;
    const matchesMonth = filterMonth ? notifMonth === filterMonth : true;

    return matchesTerm && matchesRegion && matchesRA && matchesStatus && matchesMonth;
  });

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = filteredData.slice((page - 1) * itemsPerPage, page * itemsPerPage);

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="bg-card p-4 rounded-lg border border-gray-800 flex flex-col gap-4">
         <div className="flex justify-between items-center border-b border-gray-700 pb-2 mb-2">
             <h3 className="text-gray-400 text-sm font-semibold uppercase">Filtros de Lista</h3>
             <button 
                onClick={() => generateTeamReport(filteredData)}
                className="flex items-center gap-2 bg-blue-900/30 border border-blue-500 text-blue-400 px-3 py-1 rounded text-xs font-bold hover:bg-blue-500 hover:text-white transition-colors"
            >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                Gerar Relatório de Equipe
            </button>
         </div>

         <div className="grid grid-cols-1 md:grid-cols-5 gap-4 items-end">
            <div className="relative w-full md:col-span-1">
            <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
            <input 
                type="text" 
                placeholder="Buscar..." 
                className="block w-full p-2.5 pl-10 text-sm text-white border border-gray-700 rounded-lg bg-gray-900 focus:ring-primary focus:border-primary placeholder-gray-500"
                value={searchTerm}
                onChange={(e) => { setSearchTerm(e.target.value); setPage(1); }}
            />
            </div>

            <select 
            value={filterMonth}
            onChange={(e) => { setFilterMonth(e.target.value); setPage(1); }}
            className="bg-gray-900 border border-gray-700 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block p-2.5"
            >
            <option value="">Mês Notificação</option>
            {filterOptions.months.map(m => (
                <option key={m} value={m}>{m}</option>
            ))}
            </select>

            <select 
            value={filterStatus}
            onChange={(e) => { setFilterStatus(e.target.value); setPage(1); }}
            className="bg-gray-900 border border-gray-700 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block p-2.5"
            >
            <option value="">Todos Status</option>
            {statusOptions.map(opt => (
                <option key={opt} value={opt}>{opt}</option>
            ))}
            </select>

            <select 
            value={filterRegion}
            onChange={(e) => { setFilterRegion(e.target.value); setPage(1); }}
            className="bg-gray-900 border border-gray-700 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block p-2.5"
            >
            <option value="">Região Saúde</option>
            {filterOptions.regions.map(r => <option key={r} value={r}>{r}</option>)}
            </select>

            <select 
            value={filterRA}
            onChange={(e) => { setFilterRA(e.target.value); setPage(1); }}
            className="bg-gray-900 border border-gray-700 text-white text-sm rounded-lg focus:ring-primary focus:border-primary block p-2.5"
            >
            <option value="">Região Adm.</option>
            {filterOptions.ras.map(r => <option key={r} value={r}>{r}</option>)}
            </select>
        </div>
      </div>

      <div className="flex justify-between text-sm text-secondary px-2">
        <span>Mostrando {paginatedData.length} de {filteredData.length} registros</span>
      </div>

      {/* Table */}
      <div className="relative overflow-x-auto shadow-md sm:rounded-lg border border-gray-800">
        <table className="w-full text-sm text-left text-gray-400">
          <thead className="text-xs text-gray-300 uppercase bg-sidebar">
            <tr>
              <th scope="col" className="px-6 py-3">Notificação</th>
              <th scope="col" className="px-6 py-3">Mês</th>
              <th scope="col" className="px-6 py-3">Paciente</th>
              <th scope="col" className="px-6 py-3">Localização</th>
              <th scope="col" className="px-6 py-3">Status</th>
              <th scope="col" className="px-6 py-3 text-right">Ações</th>
            </tr>
          </thead>
          <tbody>
            {paginatedData.length > 0 ? (
              paginatedData.map((patient, index) => {
                const geo = getGeoByCode(patient['ID_BAIRRO']);
                const notifMonth = getNotificationMonth(patient['DT_NOTIFIC']);
                return (
                  <tr key={index} className="bg-card border-b border-gray-800 hover:bg-gray-800/50 transition-colors">
                    <td className="px-6 py-4 font-mono text-primary">{patient['NU_NOTIFIC']}</td>
                    <td className="px-6 py-4 text-white">{notifMonth}</td>
                    <td className="px-6 py-4 font-medium text-white">
                      <div>{patient['NM_PACIENT'] || 'Não informado'}</div>
                    </td>
                    <td className="px-6 py-4">
                      {geo ? (
                        <div>
                          <p className="text-white text-xs">{geo.ra}</p>
                          <p className="text-[10px] text-gray-500">{geo.regiao_saude}</p>
                        </div>
                      ) : (
                        <span className="text-gray-600 italic">Não identificado</span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                         {patient['Status'] ? (
                             <span className="inline-block px-2 py-1 rounded text-xs font-semibold bg-blue-900/40 text-blue-300 border border-blue-800">
                                {patient['Status']}
                             </span>
                         ) : (
                             <span className="text-gray-600">-</span>
                         )}
                    </td>
                    <td className="px-6 py-4 text-right space-x-2">
                      <button 
                        onClick={() => onEdit(patient)}
                        className="font-medium text-blue-400 hover:underline"
                      >
                        Abrir
                      </button>
                      <button 
                        onClick={() => {
                          if (window.confirm('Tem certeza que deseja excluir este registro?')) {
                            onDelete(patient['NU_NOTIFIC']);
                          }
                        }}
                        className="font-medium text-red-500 hover:underline"
                      >
                        Excluir
                      </button>
                    </td>
                  </tr>
                );
              })
            ) : (
              <tr>
                <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                  Nenhum registro encontrado.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="flex justify-between items-center pt-4">
        <button
          onClick={() => setPage(p => Math.max(1, p - 1))}
          disabled={page === 1}
          className="px-4 py-2 text-sm font-medium text-white bg-card border border-gray-700 rounded-lg hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Anterior
        </button>
        <span className="text-sm text-gray-400">
          Página {page} de {Math.max(1, totalPages)}
        </span>
        <button
          onClick={() => setPage(p => Math.min(totalPages, p + 1))}
          disabled={page === totalPages || totalPages === 0}
          className="px-4 py-2 text-sm font-medium text-white bg-card border border-gray-700 rounded-lg hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Próxima
        </button>
      </div>
    </div>
  );
};

export default PatientList;

import React, { useState, useMemo, useEffect } from 'react';
import { PatientRecord, FieldDefinition } from '../types';
import { FIELD_GROUPS, DEFAULT_FIELD_DEF } from '../constants';
import { getGeoByCode, suggestGeoByAddress, GeoLocation } from '../sinan_geo';
import { toInputDate, fromInputDate } from '../services/csvService';
import { generateIndividualReport } from '../services/reportService';

interface PatientFormProps {
  initialData?: PatientRecord;
  dictionary: Record<string, FieldDefinition>;
  onSave: (data: PatientRecord) => void;
  onCancel: () => void;
}

const PatientForm: React.FC<PatientFormProps> = ({ initialData, dictionary, onSave, onCancel }) => {
  const [formData, setFormData] = useState<PatientRecord>(initialData || {});
  const [activeTab, setActiveTab] = useState(0);
  const [geoInfo, setGeoInfo] = useState<GeoLocation | undefined>(undefined);
  const [geoSuggestion, setGeoSuggestion] = useState<GeoLocation | undefined>(undefined);

  // Identify all fields that are present in formData or Dictionary but NOT in groups
  const otherFields = useMemo(() => {
    const groupedFields = new Set(FIELD_GROUPS.flatMap(g => g.fields));
    // Also exclude the High Priority fields (Status, Mês, Observações) as they are handled separately
    groupedFields.add('Status');
    groupedFields.add('Mês');
    groupedFields.add('Observações');

    const allKeys = Object.keys(formData);
    const unmapped = allKeys.filter(key => !groupedFields.has(key));
    return unmapped;
  }, [formData]);

  // Effect to update Geo Info when ID_BAIRRO changes
  useEffect(() => {
    const code = formData['ID_BAIRRO'];
    const found = getGeoByCode(code);
    setGeoInfo(found);

    if (!found) {
      // Try to suggest
      const address = formData['NM_LOGRADO'] || '';
      const district = formData['NM_BAIRRO'] || '';
      if (address || district) {
        const suggestion = suggestGeoByAddress(address, district);
        setGeoSuggestion(suggestion);
      } else {
        setGeoSuggestion(undefined);
      }
    } else {
      setGeoSuggestion(undefined);
    }
  }, [formData['ID_BAIRRO'], formData['NM_LOGRADO'], formData['NM_BAIRRO']]);

  const handleChange = (id: string, value: string) => {
    setFormData(prev => ({ ...prev, [id]: value }));
  };

  const handleDateChange = (id: string, inputValue: string) => {
    // Input comes as YYYY-MM-DD, we save as DD/MM/YYYY for CSV consistency
    const csvDate = fromInputDate(inputValue);
    handleChange(id, csvDate);
  };

  const applySuggestion = () => {
    if (geoSuggestion) {
      setFormData(prev => ({ ...prev, 'ID_BAIRRO': geoSuggestion.id_bairro }));
    }
  };

  const getFieldDef = (id: string) => {
    return dictionary[id] || { ...DEFAULT_FIELD_DEF, id, label: id };
  };

  const renderField = (fieldId: string) => {
    const def = getFieldDef(fieldId);
    const value = formData[fieldId] || '';

    // Validation Colors
    let borderClass = 'border-gray-700';
    let bgClass = 'bg-sidebar';

    if (!value) {
      // Empty: Alert Red
      borderClass = 'border-red-500/50';
      bgClass = 'bg-red-900/10';
    } else if (def.optionsMap && !def.optionsMap[value] && !def.options?.includes(value)) {
       // Exists but not in dictionary map (Non-standard): Warning Yellow
       borderClass = 'border-yellow-500/70';
       bgClass = 'bg-yellow-900/10';
    } else if (value) {
       // Valid: Green tint
       borderClass = 'border-green-800';
    }

    return (
      <div key={fieldId} className="flex flex-col space-y-1 mb-4">
        {/* Hierarchy: Label -> Code -> Input -> Description */}

        {/* Row 1: Main Label */}
        <label className="text-sm font-bold text-white tracking-wide" htmlFor={fieldId}>
            {def.label}
        </label>

        {/* Row 2: SINAN Code (Secondary Title) */}
        <span className="text-[10px] font-mono text-primary/80 mb-1 block">
            {def.id}
        </span>

        {/* Row 3: Input Field */}
        {def.type === 'textarea' ? (
          <textarea
            id={fieldId}
            rows={4}
            value={value}
            onChange={(e) => handleChange(fieldId, e.target.value)}
            className={`${bgClass} ${borderClass} border text-white text-sm rounded-md focus:ring-1 focus:ring-primary focus:border-primary block w-full p-2.5 placeholder-gray-600 transition-colors`}
            placeholder="Digite aqui..."
          />
        ) : def.type === 'date' ? (
            <input
            type="date"
            id={fieldId}
            // Convert DD/MM/YYYY -> YYYY-MM-DD for the input view
            value={toInputDate(value)} 
            onChange={(e) => handleDateChange(fieldId, e.target.value)}
            className={`${bgClass} ${borderClass} border text-white text-sm rounded-md focus:ring-1 focus:ring-primary focus:border-primary block w-full p-2.5 placeholder-gray-600 transition-colors appearance-none`}
          />
        ) : def.optionsMap || def.options ? (
          <select
            id={fieldId}
            value={value}
            onChange={(e) => handleChange(fieldId, e.target.value)}
            // Ensure contrast on options with bg-sidebar text-white
            className={`${bgClass} ${borderClass} border text-white text-sm rounded-md focus:ring-1 focus:ring-primary focus:border-primary block w-full p-2.5 transition-colors`}
          >
            <option value="" className="bg-sidebar text-gray-400">Selecione...</option>

            {/* Handle Dictionary Map (Code -> Meaning) */}
            {def.optionsMap ? (
                Object.entries(def.optionsMap).map(([code, meaning]) => (
                    <option key={code} value={code} className="bg-sidebar text-white">
                        {code} - {meaning}
                    </option>
                ))
            ) : (
                /* Handle Simple List */
                def.options?.map(opt => (
                    <option key={opt} value={opt.split(' - ')[0]} className="bg-sidebar text-white">
                        {opt}
                    </option>
                ))
            )}
          </select>
        ) : (
          <input
            type="text"
            id={fieldId}
            value={value}
            onChange={(e) => handleChange(fieldId, e.target.value)}
            className={`${bgClass} ${borderClass} border text-white text-sm rounded-md focus:ring-1 focus:ring-primary focus:border-primary block w-full p-2.5 placeholder-gray-600 transition-colors`}
            placeholder="Vazio"
          />
        )}

        {/* Row 4: Description */}
        <p className="text-xs text-gray-400 leading-tight pt-1">{def.description}</p>
      </div>
    );
  };

  return (
    <div className="bg-card border border-gray-800 rounded-lg shadow-xl overflow-hidden flex flex-col h-full max-h-[90vh]">
      {/* Header */}
      <div className="bg-sidebar px-6 py-4 border-b border-gray-700 flex justify-between items-center shrink-0">
        <div>
          <h2 className="text-xl font-bold text-white">Prontuário Eletrônico</h2>
          <p className="text-sm text-secondary">
            {formData['NU_NOTIFIC'] ? `Notificação: ${formData['NU_NOTIFIC']}` : 'Novo Registro'}
          </p>
        </div>
        <div className="flex gap-3">
          {formData['NU_NOTIFIC'] && (
              <button 
                onClick={() => generateIndividualReport(formData, dictionary)}
                className="px-4 py-2 rounded-md bg-gray-700 border border-gray-600 text-white hover:bg-gray-600 transition-colors flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                Imprimir Ficha Completa
              </button>
          )}
          <button 
            onClick={onCancel}
            className="px-4 py-2 rounded-md bg-transparent border border-gray-600 text-gray-300 hover:bg-gray-800 transition-colors"
          >
            Voltar
          </button>
          <button 
            onClick={() => onSave(formData)}
            className="px-4 py-2 rounded-md bg-primary text-black font-semibold hover:bg-emerald-400 transition-colors shadow-[0_0_10px_rgba(0,255,162,0.3)]"
          >
            Salvar & Fechar
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar">
        {/* Priority Section: Management */}
        <div className="p-6 bg-gray-900/50 border-b border-gray-800">
          <h3 className="text-sm font-bold text-primary mb-4 flex items-center uppercase tracking-widest">
            <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.38-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z" /></svg>
            Gestão de Caso (Prioridade)
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-4">
            {renderField('Status')}
            {renderField('Mês')}
          </div>
          <div className="w-full">
            {renderField('Observações')}
          </div>
        </div>

        {/* Geo Auto-Location Section */}
        <div className="p-6 bg-blue-900/10 border-b border-gray-800">
           <div className="flex justify-between items-center mb-4">
              <h3 className="text-sm font-bold text-blue-400 flex items-center uppercase tracking-widest">
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                Geolocalização Automática
              </h3>
              <span className="text-xs text-gray-500">Baseada no ID_BAIRRO</span>
           </div>

           <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div>
                {renderField('ID_BAIRRO')}
                {geoSuggestion && (
                   <div className="mt-2 p-3 bg-yellow-900/20 border border-yellow-700/50 rounded-md">
                     <p className="text-xs text-yellow-500 mb-1">⚠️ ID_BAIRRO ausente. Sugestão encontrada:</p>
                     <p className="text-sm text-white font-bold">{geoSuggestion.bairro} ({geoSuggestion.id_bairro})</p>
                     <p className="text-[10px] text-gray-400 mt-1 mb-2 line-clamp-2">{geoSuggestion.descricao}</p>
                     <button 
                       onClick={applySuggestion}
                       className="text-xs bg-yellow-600 text-black px-2 py-1 rounded hover:bg-yellow-500 font-semibold w-full"
                     >
                       Aplicar ID {geoSuggestion.id_bairro}
                     </button>
                   </div>
                )}
              </div>

              <div className="lg:col-span-2 grid grid-cols-2 gap-4 bg-gray-900 p-4 rounded-md border border-gray-800">
                  <div>
                    <span className="text-xs text-gray-500 uppercase">Região de Saúde</span>
                    <p className="text-white font-medium text-lg">{geoInfo?.regiao_saude || '---'}</p>
                  </div>
                  <div>
                    <span className="text-xs text-gray-500 uppercase">Região Administrativa</span>
                    <p className="text-white font-medium text-lg">{geoInfo?.ra || '---'}</p>
                  </div>
                  <div className="col-span-2">
                     <span className="text-xs text-gray-500 uppercase">Descrição do Bairro</span>
                     <p className="text-gray-300 text-sm mt-1">{geoInfo?.descricao || 'Sem informações'}</p>
                  </div>
              </div>
           </div>
        </div>

        {/* Tabs */}
        <div className="sticky top-0 z-10 bg-sidebar border-b border-gray-700 flex overflow-x-auto px-2">
          {FIELD_GROUPS.map((group, index) => (
            <button
              key={index}
              onClick={() => setActiveTab(index)}
              className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${
                activeTab === index 
                  ? 'border-primary text-primary' 
                  : 'border-transparent text-gray-400 hover:text-white hover:border-gray-600'
              }`}
            >
              {group.title}
            </button>
          ))}
          {otherFields.length > 0 && (
            <button
              onClick={() => setActiveTab(FIELD_GROUPS.length)}
              className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${
                activeTab === FIELD_GROUPS.length 
                  ? 'border-primary text-primary' 
                  : 'border-transparent text-gray-400 hover:text-white hover:border-gray-600'
              }`}
            >
              Outros / Não Mapeados ({otherFields.length})
            </button>
          )}
        </div>

        {/* Content */}
        <div className="p-6 bg-background">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {activeTab < FIELD_GROUPS.length ? (
              FIELD_GROUPS[activeTab].fields.map((fieldId) => renderField(fieldId))
            ) : (
              otherFields.map((fieldId) => renderField(fieldId))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PatientForm;

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PatientRecord, FieldDefinition } from '../types';
import { getGeoByCode } from '../sinan_geo';
import { FIELD_GROUPS } from '../constants';

// --- Helpers ---
const formatDate = () => {
  const d = new Date();
  return `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()} às ${d.getHours()}:${d.getMinutes()}`;
};

const addHeader = (doc: jsPDF, title: string, subtitle?: string) => {
  doc.setFillColor(26, 28, 35); // Dark Sidebar Color
  doc.rect(0, 0, 210, 25, 'F');

  doc.setTextColor(0, 255, 162); // Primary Green
  doc.setFontSize(16);
  doc.setFont('helvetica', 'bold');
  doc.text('SGP Auditoria - TB DF', 14, 10);

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(12);
  doc.text(title, 14, 18);

  if (subtitle) {
      doc.setFontSize(9);
      doc.setTextColor(200, 200, 200);
      doc.text(subtitle, 14, 23);
  }

  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text(`Gerado em: ${formatDate()}`, 150, 10);
};

// --- 1. Dashboard Report ---
export const generateDashboardReport = (
  filteredCount: number, 
  kpiData: { label: string, value: number, color?: string }[],
  chartsData: { title: string, data: { name: string, value: number }[] }[]
) => {
  const doc = new jsPDF();
  addHeader(doc, 'Relatório Executivo - Dashboard', `Total de Registros no Filtro: ${filteredCount}`);

  let currentY = 35;

  // KPIs
  doc.setFontSize(12);
  doc.setTextColor(0, 0, 0);
  doc.text('Indicadores Chave (KPIs)', 14, currentY);
  currentY += 5;

  const kpiRows = [kpiData.map(k => k.label), kpiData.map(k => k.value.toString())];

  autoTable(doc, {
    startY: currentY,
    head: [kpiRows[0]],
    body: [kpiRows[1]],
    theme: 'grid',
    headStyles: { fillColor: [40, 40, 40], textColor: [255, 255, 255] },
    styles: { halign: 'center', fontSize: 12, fontStyle: 'bold' }
  });

  currentY = (doc as any).lastAutoTable.finalY + 15;

  // Chart Summaries
  chartsData.forEach((chart, index) => {
    // Check for page break
    if (currentY > 250) {
        doc.addPage();
        currentY = 20;
    }

    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    doc.text(chart.title, 14, currentY);
    currentY += 2;

    const bodyData = chart.data.map(d => [d.name, d.value]);

    autoTable(doc, {
      startY: currentY + 3,
      head: [['Categoria', 'Quantidade']],
      body: bodyData,
      theme: 'striped',
      headStyles: { fillColor: [0, 150, 100] },
      margin: { left: 14, right: 120 }, // Keep it narrow
    });

    // Move Y depending on table height, but handle multi-column layout logic roughly
    // For simplicity in this text-based report, we stack them.
    currentY = (doc as any).lastAutoTable.finalY + 10;
  });

  doc.save('dashboard_report.pdf');
};

// --- 2. Team Action Report (Patient List) ---
export const generateTeamReport = (patients: PatientRecord[]) => {
  const doc = new jsPDF('l'); // Landscape
  addHeader(doc, 'Relatório de Monitoramento - Equipe', 'Lista de pacientes filtrada para ação das equipes de ponta.');

  const tableData = patients.map(p => {
     const geo = getGeoByCode(p['ID_BAIRRO']);
     const location = geo 
        ? `${geo.ra} - ${geo.bairro}\n(${geo.regiao_saude})` 
        : `ID: ${p['ID_BAIRRO'] || 'N/A'}`;

     return [
       p['NU_NOTIFIC'],
       p['NM_PACIENT'] || 'Não identificado',
       location,
       p['Status'] || 'Pendente',
       p['Observações'] || ''
     ];
  });

  autoTable(doc, {
    startY: 30,
    head: [['Notificação', 'Paciente', 'Localização / Região', 'Status Gestão', 'Observações / Pendências']],
    body: tableData,
    theme: 'grid',
    headStyles: { fillColor: [26, 28, 35], textColor: [0, 255, 162] },
    columnStyles: {
        0: { cellWidth: 30 }, // Notif
        1: { cellWidth: 50, fontStyle: 'bold' }, // Nome
        2: { cellWidth: 60, fontSize: 8 }, // Local
        3: { cellWidth: 30, fontStyle: 'bold' }, // Status
        4: { cellWidth: 'auto' } // Obs
    },
    styles: { fontSize: 9, cellPadding: 2, overflow: 'linebreak' },
  });

  doc.save('relatorio_equipe_pacientes.pdf');
};

// --- 3. Full Individual Patient Record ---
export const generateIndividualReport = (
    patient: PatientRecord, 
    dictionary: Record<string, FieldDefinition>
) => {
  const doc = new jsPDF();

  const notif = patient['NU_NOTIFIC'] || 'S/N';
  const name = patient['NM_PACIENT'] || 'Paciente';

  addHeader(doc, 'Ficha Completa do Paciente', `${name} - Notif: ${notif}`);

  let currentY = 30;

  // Process Groups
  FIELD_GROUPS.forEach(group => {
     // Check page break
     if (currentY > 270) {
         doc.addPage();
         currentY = 20;
     }

     doc.setFillColor(240, 240, 240);
     doc.rect(14, currentY, 182, 8, 'F');

     doc.setFontSize(10);
     doc.setFont('helvetica', 'bold');
     doc.setTextColor(0, 0, 0);
     doc.text(group.title.toUpperCase(), 16, currentY + 5.5);

     currentY += 10;

     // Prepare grid data for this group
     const groupData: any[][] = [];
     let currentRow: string[] = [];

     group.fields.forEach((fieldId, index) => {
        const def = dictionary[fieldId];
        const rawValue = patient[fieldId] || '';
        const label = def ? def.label : fieldId;

        // Try to decode value
        let displayValue = rawValue;
        if (def && def.optionsMap && def.optionsMap[rawValue]) {
            displayValue = `${rawValue} - ${def.optionsMap[rawValue]}`;
        }

        currentRow.push(`${label}:\n${displayValue || '--'}`);

        // 3 items per row
        if (currentRow.length === 3) {
            groupData.push(currentRow);
            currentRow = [];
        }
     });

     if (currentRow.length > 0) {
         while (currentRow.length < 3) currentRow.push(''); // fill empty
         groupData.push(currentRow);
     }

     autoTable(doc, {
        startY: currentY,
        body: groupData,
        theme: 'plain',
        styles: { fontSize: 8, cellPadding: 2, overflow: 'linebreak', valign: 'top' },
        columnStyles: {
            0: { cellWidth: 60 },
            1: { cellWidth: 60 },
            2: { cellWidth: 60 },
        },
        didParseCell: (data) => {
            // Style keys bold
            data.cell.styles.lineWidth = 0.1;
            data.cell.styles.lineColor = [200, 200, 200];
        }
     });

     currentY = (doc as any).lastAutoTable.finalY + 5;
  });

  // Observations Section at the end
  if (currentY > 250) {
      doc.addPage();
      currentY = 20;
  }

  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.text('OBSERVAÇÕES E GESTÃO', 14, currentY);
  currentY += 5;

  const obsData = [
      ['Status', patient['Status'] || 'Não informado'],
      ['Mês Ref.', patient['Mês'] || 'Não informado'],
      ['Anotações', patient['Observações'] || '']
  ];

  autoTable(doc, {
      startY: currentY,
      body: obsData,
      theme: 'grid',
      columnStyles: {
          0: { cellWidth: 40, fontStyle: 'bold', fillColor: [240, 240, 240] },
          1: { cellWidth: 'auto' }
      }
  });

  doc.save(`ficha_${notif}_${name.replace(/\s+/g, '_')}.pdf`);
};
